  const row = mode === 'create' ? null : catalog.rows.find(item => text(item.id) === text(id));
  if (mode !== 'create' && !row) return error('当前范围内没有此时间条件，请刷新列表。');
  if (['edit', 'remove'].includes(mode) && !canEdit(row)) return error('当前租户无权维护此时间条件。');
