  let route = routes[key];
  while (route?.redirect) { key=route.redirect; route=routes[key]; }
  const workbench = operatorWorkbench();
  if (workbench && ['home', 'seat-workbench'].includes(key)) { key=workbench; route=routes[key]; }
  return {key,route};
}

