  if (!route) return deny(key, '页面地址不存在。');
  if (!isVisible(route)) return deny(key, '当前角色或租户没有该页面的访问权限。');
  if(route.redirect)return window.navigateTo(route.redirect,{...(options||{})});
  const page = window.Pages[route.page];
