function open(mode, id, key) {
  if (!allowed(key)) return denied();
  if (!['create', 'view', 'edit', 'remove'].includes(mode)) return denied();
  if (!canOpen()) return false;
  const catalog = service().catalog(); if (!catalog?.ok) return error(catalog?.message || '暂时无法读取分机，请刷新后重试。');
  const row = mode === 'create' ? null : catalog.rows.find(item => text(item.id) === text(id));
  if (mode !== 'create' && !row) return error('当前范围内没有此分机，请刷新列表。');
  if (mode === 'create' && !tenantRows().length) return error('请先为当前 AliCti 账号绑定已启用云呼叫的业务租户。');
  if (mode === 'edit' && text(row.type) !== '2') return error('当前仅维护软电话分机。');
  const values = row ? Object.fromEntries([...fields, 'tenantId'].map(field => [field, text(row[field])])) : newValues();
  editor = { mode, id: row?.id, row: row ? copy(row) : null, context: copy(context()), key: scopeKey(), revision: catalog.revision, values, initial: JSON.stringify(values), dirty: false, pending: false, routeHash: location.hash };
  draw(); return true;
}

function draw() {
  if (!editor || !allowed(editor.key)) return invalidate();
  const title = { create: '新增分机', edit: '编辑分机', view: '分机详情', remove: '删除分机', import: '从 AliCti 导入分机' }[editor.mode];
  let body = '', button = '', blocked = false;
  if (['create', 'edit'].includes(editor.mode)) { body = form(); button = editor.mode === 'create' ? '创建分机' : '保存修改'; }
  else if (editor.mode === 'view') body = details();
  else if (editor.mode === 'remove') {
    const used = usage(editor.row); blocked = !used.ok || used.count > 0;
    body = `<p class="extension-delete-note">确认删除分机 <strong>${esc(editor.row.exten)}</strong>？</p><p class="extension-delete-note">删除后，该分机将不能再用于坐席接听。</p>${blocked ? `<p class="extension-usage-note">${esc(!used.ok ? used.message || '暂时无法核对使用情况，请刷新后重试。' : `使用坐席：${names(used)}。请先在坐席资料中解除使用关系。`)}</p>` : ''}`; button = '确认删除';
  } else if (editor.mode === 'import') { body = importForm(); button = '导入所选分机'; blocked = !editor.candidates?.ok || !editor.candidates.rows.length; }
  body += '<div id="extension-resource-error" class="extension-error" role="alert"></div><div id="extension-discard" class="extension-discard" hidden><p>当前内容尚未保存，是否放弃修改？</p><button class="btn" onclick="ExtensionManagement.cancelClose()">继续编辑</button><button class="btn btn-primary" onclick="ExtensionManagement.close(true)">放弃修改并关闭</button></div>';
  ui.openLayer(layerId, `<div class="layer-header"><h2>${title}</h2><button type="button" aria-label="关闭" onclick="ExtensionManagement.close()">×</button></div><div class="layer-body extension-resource-body">${body}</div><div class="layer-footer"><button class="btn" onclick="ExtensionManagement.close()">${editor.mode === 'view' ? '关闭' : '取消'}</button>${button ? `<button id="extension-save" class="btn btn-primary ${editor.mode === 'remove' ? 'btn-danger' : ''}" ${blocked ? 'disabled' : ''} onclick="ExtensionManagement.save()">${button}</button>` : ''}</div>`, 'wide', { objectKey: `extension:${editor.mode}:${editor.id ?? ''}` });
}

implementation_evidence.source_quote:
function openLayer(id, content, size, navigation = {}) {
  const previous = document.getElementById(id);
  const discardKey = navigation.discardKey || navigation.objectKey || id;
  const previousDirty = previous?._discardKey === discardKey && (previous._discardDirty ||
    (previous._discardBaseline !== undefined && layerFormSnapshot(previous) !== previous._discardBaseline));
  const returnFocus = previous?._returnFocus || document.activeElement;
  const topLayer = Array.from(document.querySelectorAll('.platform-layer')).sort((a,b)=>Number(a.style.zIndex)-Number(b.style.zIndex)).at(-1);
  const enteringAnotherView = previous && navigation.objectKey && previous._navigation?.objectKey && (navigation.objectKey !== previous._navigation.objectKey || topLayer !== previous);
  const previousView = enteringAnotherView ? previous : previous?._previousLayer;
  previous?.remove();
  const node = document.createElement('div');
  node.id = id;
  node.className = 'platform-layer';
  node.innerHTML = `<div class="layer-backdrop" onclick="PlatformUI.closeLayer('${id}')"></div><div class="layer-panel ${size || ''}" onclick="event.stopPropagation()">${content}</div>`;
  document.body.appendChild(node);
  node._returnFocus = returnFocus;
  node._previousLayer = previousView;
  node._navigation = navigation;
  node._discardKey = discardKey;
  node._discardDirty = !!previousDirty;
  if(navigation.nonModal) node.dataset.nonModal='true';
  if(navigation.kind==='confirmation')node.dataset.dialogKind='confirmation';
  else if(!previous||enteringAnotherView){node.classList.add('drawer-entering');node.addEventListener('animationend',()=>node.classList.remove('drawer-entering'),{once:true});}
  node.style.zIndex = String(nextLayerZIndex());
  const panel = node.querySelector('.layer-panel');
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-modal', navigation.nonModal?'false':'true');
  panel.tabIndex = -1;
  const header = panel.querySelector('.layer-header');
  if (header) {
    header.classList.add('secondary-dialog-header');
    let close = Array.from(header.querySelectorAll('button')).find(button => /[×✕✖]/.test(button.textContent) || /关闭/.test(button.getAttribute('aria-label') || ''));
    if (!close) {
      close = document.createElement('button');
      close.type = 'button'; close.textContent = '×';
      close.onclick = () => closeLayer(id);
      header.appendChild(close);
    }
    close.classList.add('secondary-close');
    close.setAttribute('aria-label', '关闭'); close.title = '关闭';
    const back = document.createElement('button');
    back.type = 'button'; back.className = 'secondary-back';
    back.textContent = '← 返回'; back.setAttribute('aria-label', '返回上一页');
    back.onclick = () => close.click();
    header.prepend(back);
    node.querySelector('.layer-backdrop').onclick = () => closeLayerFromBackdrop(node, () => close.click());
    const title = header.querySelector('h2,h3');
    if (title) { title.id = title.id || id + '-title'; panel.setAttribute('aria-labelledby', title.id); }
  }
  if(!header) node.querySelector('.layer-backdrop').onclick = () => closeLayerFromBackdrop(node, () => closeLayer(id));
  queueMicrotask(() => { if(node.isConnected) node._discardBaseline = layerFormSnapshot(node); });
  document.body.classList.add('layer-open');
  requestAnimationFrame(() => { if (!node.isConnected) return; node.classList.add('open'); panel.focus({preventScroll:true}); });
}

