  else if (humanView()) items = [
    card('联系客户数', s.customers, 'customers', '按当前租户和有效客户手机号去重。', `号码未识别 ${s.customerUnknown} 条`),
    card('关联通话', s.total, 'total', '当前坐席 / 服务技能所关联的已结束通话尝试。'),
