      {key:'id',label:'操作',render:(_,b)=>'<button class="btn-link" onclick="CustomerTasks.open('+actionArg(b.id)+')">查看客户</button>'}
    ],bs,{emptyText:manager()?'暂无导入批次':'暂无分配给我的客户批次'})+'</article></section>';
