  var runningTask = rows.find(function (row) { return !row.isWizardDraft && ['执行中', '已暂停', '异常'].includes(row.status); }) || rows.find(function (row) { return !row.isWizardDraft; });
  var journeyActions = {
    prepare: "ScenarioReadiness.open('" + scenarioType + "')",
    records: "RouteRuntime.openSecondary('cloud-call-records',{type:'" + type + "'})"
  };
  if (runningTask) journeyActions.monitor = "CloudTaskWorkspace.openTask('" + runningTask.taskId + "')";
  return '<section class="platform-page cloud-task-page">' +
    ui.pageHeader(isPredictive ? '预外呼任务' : '自动外呼任务', isPredictive ? '批量呼叫客户，接通后再分配空闲坐席。' : '按照已配置的语音流程批量完成自动通知或按键交互。') +
    ui.journey({ current: 'create', context: (isPredictive?'预外呼':'自动外呼') + ' · 任务列表', branch: '任务型场景', actions: journeyActions }) +
    '<div class="filter-panel"><label class="field"><span>任务名称</span><input id="cloudTaskKeyword" value="' + esc(state.keyword) + '" placeholder="请输入任务名称"></label><label class="field"><span>任务状态</span><select id="cloudTaskStatus"><option value="">全部</option>' +
    ['草稿', '待分配客户', '待启动', '执行中', '已暂停', '已完成', '已终止', '异常'].map(function (status) { return '<option' + (state.status === status ? ' selected' : '') + '>' + status + '</option>'; }).join('') +
    '</select></label><div class="filter-actions"><button class="btn" onclick="window.Pages[\'cloud-call-tasks\'].resetFilters(\'' + type + '\')">重置</button><button class="btn btn-primary" onclick="window.Pages[\'cloud-call-tasks\'].query(\'' + type + '\')">查询</button></div></div>' +
    '<div class="cloud-task-list-shell">' + ui.toolbar('<button class="btn btn-primary" onclick="window.Pages[\'cloud-call-tasks\'].openCreate(\'' + type + '\')">+ 新建任务</button>'+(isPredictive?'<button class="btn btn-primary" type="button" id="predictiveImportCustomers" onclick="CloudTaskWorkspace.openCustomerImport()">导入客户</button>':'')+'<button class="btn" onclick="window.Pages[\'cloud-call-tasks\'].exportTasks(\'' + type + '\')">导出</button>', '<span>' + ui.help(helpText, '任务说明') + '</span>') +
    ui.table([
      { key: 'orderNo', label: '序号', width: '64px' },
      { key: 'name', label: '任务名称', render: function (value, row) { return '<button class="table-link" onclick="window.Pages[\'cloud-call-tasks\'].openTask(\'' + esc(row.taskId) + '\')"><strong>' + esc(value) + '</strong><small>' + esc(tenantName(row.tenantId)) + ' · ' + esc(row.scheduleAt || '尚未设置执行时间') + '</small></button>'; } },
      { key: 'status', label: '状态', render: function (value, row) { return row.alictiTaskControlPending ? ui.status('待确认') + '<small>状态待核对 · 最后已知 ' + esc(value) + '</small>' : ui.status(value); } },
      { key: 'total', label: '名单条数' },
      { key: 'completed', label: '已完成' },
      { key: 'connected', label: '已接通' },
      { key: 'taskId', label: '完成进度', render: function (value, row) { var value=progress(row);return '<div class="progress-cell"><span><i style="width:' + (value??0) + '%"></i></span><small>' + (value===null?'待确认':value+'%') + '</small></div>'; } },
      { key: 'owner', label: '负责人' },
      { key: 'taskId', label: '操作', className: 'action-column', render: function (value, row) { if(isPredictive)return predictiveTaskActions(row); return '<div class="table-actions"><button onclick="window.Pages[\'cloud-call-tasks\'].openTask(\'' + esc(value) + '\')">' + (row.isWizardDraft ? '继续创建' : '查看与管理') + '</button>' + (!row.isWizardDraft&&CloudTaskWorkspace.canEditTask(row)?'<button onclick="CloudTaskWorkspace.editTask(\''+esc(value)+'\')">编辑</button>':'') + (isPredictive?CloudTaskWorkspace.customerImportButton(row,{table:true}):'')+(window.DccRuntime?.isManagedTask(row)?'<button onclick="CloudTaskWorkspace.openTask(\''+esc(value)+'\',\'dcc-records\')" data-func-id="FUNC-015">客户与处理记录</button>':'') + (!row.isWizardDraft&&isPredictive ? window.RepeatPredictive?.listTaskAction(row)||'' : '') + (row.isWizardDraft ? '<button onclick="CloudTaskWorkspace.deleteTask(\''+esc(value)+'\')">删除</button>' : '') + '</div>'; } }
    ], pageRows, { emptyText: '未找到符合条件的任务', emptyDetail: '可重置筛选或新建任务。', footer: ui.pagination(rows.length, state.page, pageSize, "window.Pages['cloud-call-tasks'].setPage.bind(null,'" + type + "')") }) +
    '</div></section>';
}

function openTask(taskId, tab) {
  const draft = drafts.find(item => !item.editTaskId && (item.taskId === taskId || item.draftId === taskId));
  if (draft && draft.status !== '已提交') return start(draft.type, draft.draftId);
  const task = taskById(taskId);
  if (!canAccessObject(task)) return false;
  const current = RouteRuntime.snapshot();
  const options = { taskId, tab: tab==='results'?'calls':tab || 'overview', refreshOnClose: true };
  if (current?.key === 'cloud-task-center' && current.options?.taskId === taskId) return navigateTo('cloud-task-center', options);
  return RouteRuntime.openSecondary('cloud-task-center', options);
}

function renderCenter(options) {
  const context = readCenterContext(options);
  const row = taskById(context.taskId);
  if (!row || !AppState.authorizeObject('', row)) return `<section class="platform-page">${ui.pageHeader('任务中心', '未找到当前权限范围内的任务。')}<div class="panel-card"><div class="panel-body">${ui.empty('请从预外呼或自动外呼任务列表进入')}</div></div></section>`;
  saveCenterContext(row.taskId, context.tab);
  window.DccRecords?.syncCallScope?.(row.taskId,context.tab);
  const managed=window.DccRuntime?.isManagedTask(row),recordResult=managed?window.DccRuntime.taskRecords(row.taskId):null;
  const localCount=recordResult?.ok?recordResult.data.records.length:'待核';
  const statusLabel=row.alictiTaskControlPending?'待确认':managed?row.providerStatus||'供应商状态待核':row.status;
  const currentJourneyStage = context.tab === 'calls' ? 'records' : 'monitor';
  const callSummary=managed?window.DccRuntime.taskProgressView(row.taskId):null;
  const callCount=managed?(callSummary?.ok?callSummary.data.callSummary.calls:'待确认'):taskCalls(row).length;
  const journeyActions = {
    prepare: `ScenarioReadiness.open('${row.callType === '预外呼' ? 'PREDICTIVE' : 'IVR_OUTBOUND'}','${row.tenantId}')`,
    create: `RouteRuntime.openSecondary('${routeForType(row.callType)}')`,
    monitor: `CloudTaskWorkspace.openTask('${row.taskId}','overview')`,
    records: `CloudTaskWorkspace.setTaskTab('calls')`,
    results: `CloudTaskWorkspace.setTaskTab('calls')`
  };
  return `<section class="platform-page cloud-task-center" data-task-sync-id="${esc(row.taskId)}">
    ${ui.pageHeader(`${typeLabel(row.callType)}任务详情`, `${esc(tenant(row.tenantId).name || '当前租户')} · 负责人 ${esc(row.owner || '—')}`, `<button class="btn" onclick="RouteRuntime.back({fallback:'${routeForType(row.callType)}'})">返回</button>${centerActions(row)}`)}
    ${ui.journey({ current: currentJourneyStage, context: `${row.name} · ${row.alictiTaskControlPending?'状态待核对':statusLabel}`, branch: '当前任务范围', actions: journeyActions })}
    <div class="task-center-hero"><div><span>任务名称</span><h2>${esc(row.name)}</h2></div><div><span>${managed?'供应商状态':'任务状态'}</span>${ui.status(statusLabel)}${row.alictiTaskControlPending?`<strong>状态待核对</strong><small>最后已知：${esc(managed?row.providerStatus||'未记录':row.status)}</small>`:''}${row.stopNewDialing?'<small>已停止发起新呼叫</small>':''}</div><div><span>执行时间</span><strong>${esc(row.scheduleAt || '—')}</strong><small>${row.startedAt ? `实际启动 ${esc(row.startedAt)}` : '实际启动后记录'}</small></div>${managed?`<div><span>任务记录</span><strong>已保存客户 ${localCount}</strong><small>呼叫进展见通话记录</small></div>`:`<div><span>当前进度</span><strong>${percent(row)}%</strong><small>${row.completed || 0} / ${row.total || 0}</small></div>`}</div>
    <div class="task-center-tabs">${centerTabs.filter(item=>(item.key!=='dcc-records'||window.DccRuntime?.isManagedTask(row))&&(item.key!=='customers'||!window.DccRuntime?.isManagedTask(row))&&(item.key!=='priority'||row.callType==='预外呼')).map(item=>`<button class="${item.key===context.tab?'active':''}" onclick="CloudTaskWorkspace.setTaskTab('${item.key}')">${item.label}${item.key==='calls'?` <span data-task-calls-count>${callCount}</span>`:''}</button>`).join('')}</div>
    <div class="task-center-body">${centerBody(row, context.tab)}</div>
  </section>`;
}

function centerActions(row) {
  const buttons = [];
  if(row.displayOnly)return '';
  if(!canAccessObject(row))return '';
  if(row.alictiTaskControlPending)buttons.push('<span class="form-help">当前状态待核对；操作前将重新查询任务状态。</span>');
  if(canEditTask(row))buttons.push(`<button class="btn" onclick="CloudTaskWorkspace.editTask('${esc(row.taskId)}')">编辑任务</button>`);
  if (['待分配客户','待启动','异常'].includes(row.status)) buttons.push(`<button class="btn danger" onclick="CloudTaskWorkspace.controlTask('${row.taskId}','terminate')">终止任务</button>`);
  if (canDeleteTask(row)) buttons.push(`<button class="btn danger" onclick="CloudTaskWorkspace.deleteTask('${row.taskId}')">${row.repeatContact?'撤销本次安排':'删除任务'}</button>`);
  if(row.callType==='预外呼')buttons.push(customerImportButton(row));
  if(window.DccRuntime?.isManagedTask(row))buttons.push(`<button class="btn" onclick="CloudTaskWorkspace.setTaskTab('dcc-records')">客户与处理记录</button>`);
  else if (!CustomerTasks.canImportToTask(row)&&['待分配客户','待启动'].includes(row.status)) buttons.push(`<button class="btn" onclick="CustomerTasks.open()">分配客户</button>`);
  if (row.resourcePause) buttons.push('<span class="form-help">号码停用已阻止新拨号；恢复号码后，待启动任务可启动，执行中任务先暂停再继续。</span>');
  if (row.availabilityPause?.reason==='AVAILABLE_SEATS_BELOW_MIN') buttons.push(`<span class="form-help">可用座席 ${esc(row.availabilityPause.availableAgentCount)} 人，低于设置的 ${esc(row.availabilityPause.threshold)} 人，任务已自动暂停。${Number(row.autoStart)===1?'人数达到设置值后自动启动。':'人数恢复后需手动继续。'}</span>`);
  if (window.DccRuntime?.isManagedTask(row)?managedReadyForStart(row):row.status === '待启动') buttons.push(Number(row.autoStart)===1?`<span class="form-help">已设置定时开始：${esc(row.scheduleAt||'按计划时间')}；${window.CloudTaskWorkspace?.isPersistedLocalDemoTask?.(row)?'到点核对名单和接听条件后启动（本地演示）。':'由供应商按定时配置执行，实际状态需核对。'}</span>`:`<button class="btn btn-primary" onclick="CloudTaskWorkspace.controlTask('${row.taskId}','start')">启动任务</button>`);
  if (row.status === '执行中') buttons.push(`<button class="btn" onclick="CloudTaskWorkspace.controlTask('${row.taskId}','pause')">暂停任务</button><button class="btn danger" onclick="CloudTaskWorkspace.controlTask('${row.taskId}','terminate')">终止任务</button>`);
  if (row.status === '已暂停') buttons.push(`${row.availabilityPause?.reason==='AVAILABLE_SEATS_BELOW_MIN'&&Number(row.autoStart)===1?'':!row.resourcePause || canRestoreResourceTask(row) ? `<button class="btn btn-primary" onclick="CloudTaskWorkspace.controlTask('${row.taskId}','resume')">${row.resourcePause ? '恢复任务' : '继续任务'}</button>` : '<span class="form-help">号码停用保护中，需有权管理员逐项恢复</span>'}<button class="btn danger" onclick="CloudTaskWorkspace.controlTask('${row.taskId}','terminate')">终止任务</button>`);
  buttons.push(`<button class="btn" onclick="CloudTaskWorkspace.copyTask('${row.taskId}')">复制任务</button>`);
  return buttons.join('');
}

function deleteTask(id,confirmed=false){
  const draft=drafts.find(d=>d.draftId===id||d.taskId===id),row=draft&&canAccessDraft(draft)?draft:taskById(id),isDraft=row===draft;
  if(!row||!(isDraft?canAccessDraft(row):canDeleteTask(row)))return showToast('仅管理员可删除尚未提交供应商、未启动且无通话记录的任务','warning');
  const repeat=!!(row.repeatContact||row.repeatPredictive);
  if(!confirmed)return ui.confirm({id:'task-delete',title:repeat?'撤销本次安排':'删除任务',danger:true,body:'<p>确认'+(repeat?'撤销':'删除')+'“'+esc(isDraft?row.values.name||'未命名任务':row.name)+'”？'+(repeat?'本次再次联系安排将撤销，原客户与通话历史保留。':'此操作不可恢复。客户本身不会删除；正式关联的客户将返回待分配，草稿预选不占用客户。')+'</p>',confirmText:repeat?'确认撤销':'确认删除',onConfirm(){deleteTask(id,true);}});
  if(isDraft){drafts=drafts.filter(d=>d!==draft);persist();}
  else {
    const before=structuredClone(row),deleted={...structuredClone(row),status:'已删除',deletedAt:nowText()};
    try {
      persistCreatedTask(deleted);
      if(!CustomerTasks.releaseUnstartedTask(row)){
        // Only this deletion's revision may be undone; a later task change wins.
        if(!restoreStoredTask(before,deleted))return showToast('任务删除尚未恢复，请保留浏览器数据后重试','error');
        return showToast('客户已有通话或释放失败，未删除任务','warning');
      }
    }catch(error){return showToast(error.message||'任务删除未保存，客户未改动，请重试','error');}
    removeListedTask(row.taskId);
  }
  CloudCallRuntime.addAudit?.('删除未启动任务',row.taskId||row.draftId,row.tenantId,'未启动','已删除');clearActiveContext();showToast(repeat?'本次再次联系安排已撤销，原客户与通话历史保留':'任务已删除，客户保留并返回待分配','success');ui.closeLayer('task-delete');if(['cloud-task-center','cloud-task-create'].includes(RouteRuntime.snapshot()?.key))RouteRuntime.back({fallback:routeForType(row.callType||row.type),refresh:true});else navigateTo(routeForType(row.callType||row.type));
}

