function operatorWorkbench() {
  if (AppState.get().activeDomain !== 'CLOUD_CONTACT_CENTER' || AppState.effectiveAccess().roleCode !== 'OPERATOR') return '';
  // Workbench identity follows this tenant's seat association, not phone presence.
  return window.AgentWorkbench?.hasSeat() ? 'seat-workbench' : 'home';
}

function eligible() {
  const s = state();
  return root.TenantSupervisorPolicy?.isTenantAdmin() === true && s.activeDomain === 'CLOUD_CONTACT_CENTER' &&
    root.AppState.hasCapability('CLOUD_CONTACT_CENTER') && (data.tenants || []).some(t => t.tenantId === s.tenantId && t.enterpriseId === s.enterpriseId && t.status === '启用');
}

function isTenantAdmin() {
  const app = root.AppState, state = app?.get?.(), access = app?.effectiveAccess?.();
  if (!state || !access?.valid || access.roleCode !== 'ADMIN' || app?.isReady?.() === false || state.activeDomain !== 'CLOUD_CONTACT_CENTER') return false;
  if (access.accountId !== state.accountId || access.tenantId !== state.tenantId || access.enterpriseId !== state.enterpriseId) return false;
  return powerFor({ accountId: state.accountId, tenantId: state.tenantId, enterpriseId: state.enterpriseId }) === 1;
}

function effectiveAccess() {
  const tenant = currentTenant();
  const member = currentMembership();
  const instance = currentInstance();
  const validDomain = availableDomains().includes(state.activeDomain);
  const valid = isReady() && account().status === '启用' && !!tenant && tenant.status === '启用' && tenant.enterpriseId === state.enterpriseId && !!member && !!instance && instance.status === 'RUNNING' && validDomain;
  return {
    valid,
    accountId: state.accountId,
    roleCode: member?.roleCode || '',
    roleId: member?.roleCode || '',
    roleLabel: roleLabels[member?.roleCode] || '',
    tenantId: tenant?.tenantId || '',
    tenantType: tenant?.builtIn ? 'built-in' : 'business',
    capabilitySet: tenant?.capabilitySet || [],
    activeDomain: state.activeDomain,
    organizationScope: tenant?.organizationScope || '',
    enterpriseId: instance?.enterpriseId || '',
    enterpriseIds: instance ? [instance.enterpriseId] : [],
    tenantIds: tenantIdsInScope(),
