function saveApplication(input) {
  if(isReadOnlyProjection())return readOnlyFailure();
  if(!canManageApplications())return failure('FORBIDDEN','仅超级管理员可修改应用。');
  const fresh=applicationWriteGuard(input);if(!fresh.ok)return fresh;
  const index=state.applications.findIndex(row=>row.applicationId===text(input?.applicationId));
  if(index<0)return failure('UNKNOWN_APPLICATION','应用不存在或已删除。');
  const checked=applicationValues(input,state.applications[index]);if(!checked.ok)return checked;
  const next=clone(state);Object.assign(next.applications[index],checked.data,{savedAt:new Date().toISOString()});
  return saveApplications(next,next.applications[index]);
}

function saveApplication(input) {
  if(isReadOnlyProjection())return readOnlyFailure();
  if(!canManageApplications())return failure('FORBIDDEN','仅超级管理员可修改应用。');
  const fresh=applicationWriteGuard(input);if(!fresh.ok)return fresh;
  const index=state.applications.findIndex(row=>row.applicationId===text(input?.applicationId));
  if(index<0)return failure('UNKNOWN_APPLICATION','应用不存在或已删除。');
  const checked=applicationValues(input,state.applications[index]);if(!checked.ok)return checked;
  const next=clone(state);Object.assign(next.applications[index],checked.data,{savedAt:new Date().toISOString()});
  return saveApplications(next,next.applications[index]);
}

function remove(id) {
  if(!allowed() || saving)return false;
  const latest=runtime().snapshot(),row=latest.ok && latest.data.applications.find(item=>item.applicationId===id);
  if (!row) {notify(latest.reason || '应用已变化，请刷新后重试','warning');return false;}
  const originalContext = context;
  ui().confirm({ id: 'dcc-application-delete-confirm', title: '删除应用', body: '<div data-func-id="FUNC-021"><p>确定删除“' + esc(row.name || row.applicationId) + '”？</p><p>删除后，该应用的接入密钥将无法继续获取 token。</p></div>', confirmText: '删除应用', danger: true, onConfirm() {
    if (!allowed() || context !== originalContext || !application(id)) { notify('应用或当前账号已变化，请重新打开', 'warning'); return false; }
    const result = runtime().deleteApplication({ applicationId: id, expectedRevision:latest.data.revision });
