  if (generation !== token || captured !== contextKey() || !currentTarget.ok || currentTarget.target.contactCenterIdentityId !== expectedIdentity) {
    if (operation?.token === token) operation = null;
    return fail('账号、租户或坐席授权已变化，已忽略旧操作结果');
