evidence.source_quote:
function open(kind,id,previewOnly=false) {
  if(!states[kind]||!model.canManage()||context!==model.context()) return showToast('工作范围已变化，请刷新后操作','warning');
  const data=catalog(); if(!data.ok) return showToast(data.message,'warning');
  const value=id ? rowsOf(kind,data).find(row=>row.id===id) : initial(kind);
  if(!value) return showToast('当前租户没有此配置','warning');
  flowChanged=false;
  editor={kind,values:clone(value),initialValues:clone(value),scope:clone(currentScope()),context:model.context(),revision:data.revision,previewOnly,creating:!id};
  draw();
}

function catalog(source = {}) {
  const scope = scopeOf(source);
  if (!allowed(scope)) return {ok:false,rows:[],fields:[],message:'请选择当前账号下的使用租户',scope,context:context()};
  try {
    const {data} = load(), bundle = data.scopes.find(row => sameScope(row,scope)) || defaults();
    return {ok:true,rows:clone(bundle.types),fields:clone(bundle.fields),scope,revision:data.revision,context:context()};
  } catch (_) { return {ok:false,rows:[],fields:[],message:'业务配置暂时无法读取，请刷新后重试',scope,context:context()}; }
}

function mutate(source, options, change) {
  if (!canManage() || !allowed(source)) return fail('当前账号无权维护此租户的业务配置');
  if (options.expectedContext !== undefined && options.expectedContext !== context()) return fail('工作范围已变化，请重新打开后操作');
  try {
    const loaded = load();
    if (options.expectedRevision !== undefined && options.expectedRevision !== loaded.data.revision) return fail('业务配置已更新，请重新打开后操作');
    const scope = scopeOf(source), next = clone(loaded.data);
    let target = next.scopes.find(row => sameScope(row,scope));
    if (!target) { target = {...scope,...defaults()}; next.scopes.push(target); }
    const result = change(target); if (!result.ok) return result;
    if (!validateScope(target)) return fail('业务配置校验失败，请核对关联关系后重试');
    if (root.localStorage.getItem(storageKey) !== loaded.raw) return fail('业务配置已更新，请重新打开后操作');
    next.revision++; root.localStorage.setItem(storageKey,JSON.stringify(next));
    return {...result,revision:next.revision,scope};
  } catch (_) { return fail('业务配置未能保存，请保留填写内容并重试'); }
}

function open(kind,id,previewOnly=false) {
  if(!states[kind]||!model.canManage()||context!==model.context()) return showToast('工作范围已变化，请刷新后操作','warning');
  const data=catalog(); if(!data.ok) return showToast(data.message,'warning');
  const value=id ? rowsOf(kind,data).find(row=>row.id===id) : initial(kind);
  if(!value) return showToast('当前租户没有此配置','warning');
  flowChanged=false;
  editor={kind,values:clone(value),initialValues:clone(value),scope:clone(currentScope()),context:model.context(),revision:data.revision,previewOnly,creating:!id};
  draw();
}

function save() {
  if(!isActive()||editor.previewOnly) return error('工作范围已变化，请重新打开');
  const methods={category:model.save,field:model.saveField};
  const result=methods[editor.kind](editor.values,editor.scope,{expectedContext:editor.context,expectedRevision:editor.revision});
  if(!result.ok) return error(result.message);
  if(editor.parent) {
    const child=editor, parent=editor.parent;
    parent.revision=model.catalog(parent.scope).revision;
    if(child.kind==='field'&&parent.kind==='category'&&!parent.values.fields.some(ref=>ref.fieldId===child.values.id)) parent.values.fields.push({fieldId:child.values.id,enabled:true,required:false});
    editor=parent; flowChanged=true; draw(); showToast(result.message,'success'); return;
  }
  dismissAll(); flowChanged=false; refresh(); showToast(result.message,'success');
}

