  if(!ids.length&&picker.initialIds.length&&!confirmed){ui.confirm({id:'queue-picker-decision',title:'解除全部关联？',body:'<p>解除全部技能关联后，队列将不再有本地关联技能。确认解除？</p>',confirmText:'确认解除全部关联',onConfirm:()=>saveAssociation(true)});return;}
